            Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.System), "sc.exe");

        private static void Main(string[] args)
        {
            if (args.Length > 0)
            {
                switch (args[0].ToLowerInvariant())
                {
                    case "install":   Install();   return;
                    case "uninstall": Uninstall(); return;
                    case "start":     RunSc($"start {ServiceName}"); return;
                    case "stop":      RunSc($"stop {ServiceName}");  return;
                }
            }

            ServiceBase.Run(new ImplantService());
        }

        private static int RunSc(string arguments)
        {
